parts.openscad_module:
$fn = 128;

knob_d       = 30;
knob_h       = 15;
grip_count   = 30;
grip_d       = 2.5;
bore_d       = 3.2;

module knurled_knob() {
  difference() {
    union() {
      cylinder(h = knob_h, d = knob_d, center = true);
      for (i = [0 : grip_count - 1])
        rotate([0, 0, 360 * i / grip_count])
          translate([knob_d/2, 0, 0])
            cylinder(h = knob_h * 0.8, d = grip_d, center = true, $fn = 12);
    }
    cylinder(h = knob_h + 2, d = bore_d, center = true, $fn = 32);
  }
}

knurled_knob();
